FIRST_COLOR = "#3B82F6"


def prefix_to_strategy(apps, schema_editor):
    """The Grok Bot page's old single "Bot order ID prefix" becomes a first strategy named after it
    (e.g. "eng"), to rename on the page. A blank prefix (whole account) needs no strategy."""
    GrokBotSettings = apps.get_model("albright_trading_app", "GrokBotSettings")
    BotStrategy = apps.get_model("albright_trading_app", "BotStrategy")
    for row in GrokBotSettings.objects.exclude(order_id_prefix=""):
        prefix = row.order_id_prefix.strip()
        if prefix and not BotStrategy.objects.filter(user_id=row.user_id).exists():
            BotStrategy.objects.create(user_id=row.user_id, name=prefix[:80], prefixes=[prefix], color=FIRST_COLOR,
                                       status="active", display_order=0)


def strategy_to_prefix(apps, schema_editor):
    """Going back: each user's first strategy's first prefix becomes the single setting again."""
    GrokBotSettings = apps.get_model("albright_trading_app", "GrokBotSettings")
    BotStrategy = apps.get_model("albright_trading_app", "BotStrategy")
    for strategy in BotStrategy.objects.order_by("user_id", "display_order", "pk"):
        if strategy.prefixes and not GrokBotSettings.objects.filter(user_id=strategy.user_id).exists():
            GrokBotSettings.objects.create(user_id=strategy.user_id, order_id_prefix=strategy.prefixes[0][:48])


